(7058799, 1074142, 47906, '<td valign="top">Beautiful Colors and detail in the feathers of this lorikeet. Love the focusing on the eye and the shallow DOF.</td>', 'Beautiful Colors and detail in the feathers of this lorikeet. Love the focusing on the eye and the shallow DOF.', '2013-07-01 20:00:04.000000', NULL, 1),
(7058800, 1074100, 47906, '<td valign="top">Is it an illusion that it feels like it is upside down? Its a beutiful hall. I love the blue circles. Its my favorite color. Stunning detail and texture throughout the frame.</td>', 'Is it an illusion that it feels like it is upside down? Its a beutiful hall. I love the blue circles. Its my favorite color. Stunning detail and texture throughout the frame.', '2013-07-01 20:02:00.000000', NULL, 1),
