(7058804, 1074188, 47906, '<td valign="top">great detail and symmetry. Beautiful Lighting.</td>', 'great detail and symmetry. Beautiful Lighting.', '2013-07-01 20:05:09.000000', NULL, 1),
(7058805, 1074091, 47906, '<td valign="top">Great Macro. Love the tiny crsytline structures which I will guess are frost. Love the leaves sticking out like it is breaking free from the frost/ice. Great Depth of focus, great control.</td>', 'Great Macro. Love the tiny crsytline structures which I will guess are frost. Love the leaves sticking out like it is breaking free from the frost/ice. Great Depth of focus, great control.', '2013-07-01 20:06:46.000000', NULL, 1),
(7058806, 1072749, 47906, '<td valign="top">Good use of frame and composition to creat depth. Love the detail of the rust on the front of the car I am amazed the headlights are still in there. I really like the toned down processing here to give the old tyme feeling.</td>', 'Good use of frame and composition to creat depth. Love the detail of the rust on the front of the car I am amazed the headlights are still in there. I really like the toned down processing here to give the old tyme feeling.', '2013-07-01 20:09:08.000000', NULL, 1),
(7058807, 1073993, 47906, '<td valign="top">Very Dramatic processing here. Very interesting HDR type of feel, perhaps a bit over done as I do see a few oversharpen halos here and there. But overall very well done</td>', 'Very Dramatic processing here. Very interesting HDR type of feel, perhaps a bit over done as I do see a few oversharpen halos here and there. But overall very well done', '2013-07-01 20:13:02.000000', NULL, 1),
(7058808, 1072939, 47906, '<td valign="top">Beautiful family portrait. The sharpness and detail on this is great. you can see the beads of water on the adult loons head. Feels like the water is slightly tilted in the clockwise direction if looking at the entire frame but a beautiful capture none the less.</td>', 'Beautiful family portrait. The sharpness and detail on this is great. you can see the beads of water on the adult loons head. Feels like the water is slightly tilted in the clockwise direction if looking at the entire frame but a beautiful capture none the less.', '2013-07-01 20:15:57.000000', NULL, 1),
(7058809, 1073629, 47906, '<td valign="top">Great contrast between your puffin and your sky. I like the movment of the wings with the detail still on the eye and beak. Its like he is trying to tell others he has some food. Nice shot.</td>', 'Great contrast between your puffin and your sky. I like the movment of the wings with the detail still on the eye and beak. Its like he is trying to tell others he has some food. Nice shot.', '2013-07-01 20:17:25.000000', NULL, 1),
