(7061704, 1073672, 43774, '<td valign="top">Stunning. My favourite of the challenge.</td>', 'Stunning. My favourite of the challenge.', '2013-07-06 22:10:03.000000', NULL, 1),
(7061706, 1072392, 65234, '<td valign="top">No, we are territorial little monsters ;-) Not the most jaw-dropping Hummer photo I''ve ever seen but getting two at once is HARD.</td>', 'No, we are territorial little monsters ;-) Not the most jaw-dropping Hummer photo I''ve ever seen but getting two at once is HARD.', '2013-07-06 22:36:48.000000', NULL, 1),
(7061707, 1074095, 65234, '<td valign="top">He looks ... shocked and appalled.  Very nice light and detail on him.  Not sure I would have kept that leaf at the top in the composition ... maybe cropped a bit more top and right so his eye was close to or on the Rule of Thirds.  Very conventional of me, I know.</td>', 'He looks ... shocked and appalled.  Very nice light and detail on him.  Not sure I would have kept that leaf at the top in the composition ... maybe cropped a bit more top and right so his eye was close to or on the Rule of Thirds.  Very conventional of me, I know.', '2013-07-06 22:38:43.000000', NULL, 1),
(7061708, 1074091, 65234, '<td valign="top">Nice ice crystals.</td>', 'Nice ice crystals.', '2013-07-06 22:38:58.000000', NULL, 1),
(7061709, 1074178, 65234, '<td valign="top">Hey, it only looks a wee bit askew.  Which drugs are we on?</td>', 'Hey, it only looks a wee bit askew.  Which drugs are we on?', '2013-07-06 22:39:48.000000', NULL, 1),
(7061710, 1073817, 65234, '<td valign="top">Awwww :-)))  Absolutely darling.</td>', 'Awwww :-)))  Absolutely darling.', '2013-07-06 22:40:24.000000', NULL, 1),
(7061711, 1074187, 65234, '<td valign="top">Love the backlighting, and the smiles.</td>', 'Love the backlighting, and the smiles.', '2013-07-06 22:40:48.000000', NULL, 1),
(7061713, 1073040, 65234, '<td valign="top">That''s a fairly astonishing capture with the head and bug in such sharp focus and a chick clearly waiting in the nest.</td>', 'That''s a fairly astonishing capture with the head and bug in such sharp focus and a chick clearly waiting in the nest.', '2013-07-06 22:42:01.000000', NULL, 1),
(7061714, 1074207, 65234, '<td valign="top">:-(((</td>', ':-(((', '2013-07-06 22:43:30.000000', NULL, 1),
(7061718, 1073970, 65234, '<td valign="top">Looks like she''s due for a shave!  Nice view she''s got.</td>', 'Looks like she''s due for a shave!  Nice view she''s got.', '2013-07-06 22:52:42.000000', NULL, 1),
(7061719, 1072876, 65234, '<td valign="top">A new spin on water drop images (ha!).  Gotta'' say, it''s pretty amazing.</td>', 'A new spin on water drop images (ha!).  Gotta'' say, it''s pretty amazing.', '2013-07-06 22:52:50.000000', NULL, 1),
(7061720, 1074112, 65234, '<td valign="top">Yikes!  Serious storm.  The lightning looks sharp enough to be cutting the sky to pieces.<br/> <br/>I hate to say it, but I see dust spots (or maybe water drops).  I would''ve cleaned those up.  Still an awesome image.</td>', 'Yikes!  Serious storm.  The lightning looks sharp enough to be cutting the sky to pieces. I hate to say it, but I see dust spots (or maybe water drops).  I would''ve cleaned those up.  Still an awesome image.', '2013-07-06 22:54:50.000000', NULL, 1),
(7061721, 1074139, 65234, '<td valign="top">Lovely light.  Looks like one of the wolves at the National Zoo in DC.</td>', 'Lovely light.  Looks like one of the wolves at the National Zoo in DC.', '2013-07-06 22:55:24.000000', NULL, 1),
(7061722, 1074016, 65234, '<td valign="top">Yum; fresh worms and grubs!  Perfect timing on the capture.  The chick looks a bit washed out to me, like it needs a local contrast boost or levels adjustment.</td>', 'Yum; fresh worms and grubs!  Perfect timing on the capture.  The chick looks a bit washed out to me, like it needs a local contrast boost or levels adjustment.', '2013-07-06 22:57:53.000000', NULL, 1),
(7061723, 1072952, 65234, '<td valign="top">Nice capture of this Swallow.  So pretty.  And they are really never still for long!</td>', 'Nice capture of this Swallow.  So pretty.  And they are really never still for long!', '2013-07-06 22:58:43.000000', NULL, 1),
(7061724, 1073994, 65234, '<td valign="top">Quite verdant.</td>', 'Quite verdant.', '2013-07-06 22:58:57.000000', NULL, 1),
(7061726, 1074156, 65234, '<td valign="top">Are those catfish or carp?  Definitely looks like a bit of frenzy in the water.</td>', 'Are those catfish or carp?  Definitely looks like a bit of frenzy in the water.', '2013-07-06 22:59:39.000000', NULL, 1),
(7061727, 1074048, 65234, '<td valign="top">He''s on his own perfectly-sized little focal plane :-)</td>', 'He''s on his own perfectly-sized little focal plane :-)', '2013-07-06 23:00:56.000000', NULL, 1),
(7061728, 1073629, 65234, '<td valign="top">Puffin :-)))  I saw an article the other day about how they''re in decline.  Very sad.  Glad to see at least this one seems to be gathering enough to eat.</td>', 'Puffin :-)))  I saw an article the other day about how they''re in decline.  Very sad.  Glad to see at least this one seems to be gathering enough to eat.', '2013-07-06 23:01:48.000000', NULL, 1),
