(7061734, 1073602, 12611, '<td valign="top">Now we know exactly where the wild things are, great processing.</td>', 'Now we know exactly where the wild things are, great processing.', '2013-07-06 23:50:00.000000', NULL, 1),
(7061735, 1072324, 12611, '<td valign="top">In the end, its all about light and texture.</td>', 'In the end, its all about light and texture.', '2013-07-06 23:51:25.000000', NULL, 1),
(7061736, 1073993, 12611, '<td valign="top">the gravel is a nice touch. it centers the shot, along with the woodgrain,.</td>', 'the gravel is a nice touch. it centers the shot, along with the woodgrain,.', '2013-07-06 23:54:23.000000', NULL, 1),
(7061737, 1074207, 12611, '<td valign="top">an awesome sight, a terrible sight, I see them.</td>', 'an awesome sight, a terrible sight, I see them.', '2013-07-06 23:59:16.000000', NULL, 1),
(7061740, 1074006, 12611, '<td valign="top">One of the great things about photography, to show us the almost real, to capture the familiar sunlight retreating.</td>', 'One of the great things about photography, to show us the almost real, to capture the familiar sunlight retreating.', '2013-07-07 00:06:35.000000', NULL, 1),
(7061742, 1073597, 12611, '<td valign="top">I Like the feel, the "realness" of the shot. there are some obvious issues with the grain and noise, perhaps that adds a bit to the security camera feel of the shot.</td>', 'I Like the feel, the "realness" of the shot. there are some obvious issues with the grain and noise, perhaps that adds a bit to the security camera feel of the shot.', '2013-07-07 00:19:59.000000', NULL, 1),
(7061743, 1074173, 12611, '<td valign="top">I like the gunfight reference, great shadow, even though, noon would be the least shadow or no shadow, no mind- draw!</td>', 'I like the gunfight reference, great shadow, even though, noon would be the least shadow or no shadow, no mind- draw!', '2013-07-07 00:23:28.000000', NULL, 1),
